  /* ================= Diapositiva 8: ciudad verde con la imagen animada =================
     La imagen se anima con un shader (el follaje se mece con el viento, las nubes se desplazan despacio,
     la luz se mueve entre las hojas, la bruma baja respira) y, encima, un canvas 2D con aves que cruzan el cielo,
     hojas que caen, motas de luz y rayos de sol que pulsan. */
  const CIU_IMG = "data:image/jpeg;base64,";
  const ciuPage = document.getElementById('ciudad'), ciuFb = document.getElementById('ciuFallback');
  const ciuGLc = document.getElementById('ciuGL'), ciuFXc = document.getElementById('ciuFX');
  ciuFb.style.backgroundImage = `url(${CIU_IMG})`;
  const CIW = 1199, CIH = 672, CIZ = 1.04;
  const ciuView = (w,h) => { const k = Math.max(w/CIW, h/CIH)*CIZ; return {k, ox:(w-CIW*k)/2, oy:(h-CIH*k)/2}; };
  let ciuImgEl = null;
