    let W = 0, H = 0, dpr = 1, raf = 0, running = false, ready = false, glOK = false;
    const fx = ciuFXc.getContext('2d');
    const lay = document.createElement('canvas'), lx = lay.getContext('2d');
    const maskC = document.createElement('canvas'); maskC.width = 600; maskC.height = 336; let maskOK = false;
    const gl = ciuGLc.getContext('webgl', {antialias:false, alpha:false});
