    const flock = Array.from({length:16}, () => ({r:rr(6,34), ph:rr(0,6.283), w:rr(.34,.62), sq:rr(.35,.6), s:rr(4,6.2), fr:rr(5.5,8), fp:rr(0,6.283)}));
    const glide = Array.from({length:7}, () => ({off:rr(0,700), sp:rr(10,18), y:rr(34,96), ph:rr(0,6.283), s:rr(3.4,5), fr:rr(4,6.5)}));
    const leaves = Array.from({length:16}, () => ({x:rr(0,CIW), y:rr(0,CIH), vx:rr(10,26), vy:rr(14,30), s:rr(2.2,4.6), ph:rr(0,6.283), sp:rr(1.2,2.6), col:['#7ccf45','#9be05a','#d6e35a','#4f9a32'][(CR()*4)|0]}));
    const motes = Array.from({length:46}, () => ({x:rr(0,CIW), y:rr(0,CIH), vx:rr(1,6), vy:rr(-8,-2), s:rr(.5,1.4), ph:rr(0,6.283), a:rr(.25,.7)}));

