        const g = c.createLinearGradient(x0,0,x0-340,CIH); g.addColorStop(0,`rgba(255,248,205,${a.toFixed(3)})`); g.addColorStop(1,'rgba(255,248,205,0)');
        c.fillStyle = g; c.beginPath(); c.moveTo(x0,0); c.lineTo(x0+w0,0); c.lineTo(x0+w0-340-30,CIH); c.lineTo(x0-340,CIH); c.closePath(); c.fill();
