        if (l.y > CIH + 8 || l.x > CIW + 8) { l.x = rr(-40,CIW*.8); l.y = rr(-30,-4); }
        const sx = Math.abs(Math.cos(t*l.sp*1.7 + l.ph));
        c.save(); c.translate(l.x,l.y); c.rotate(Math.sin(t*l.sp + l.ph)*1.2 + l.ph);
