    const bw = Math.max(170, Math.min(W*.2, H*.46)), diag = Math.hypot(W,H), L = diag*1.12 + bw*.5;
    const bld = flMakeBuilding(bw, L, Math.min(dpr,1.25));
    const vw = ciuView(W,H);
    const T_RISE = 1900, T_HOLD = 2700, T_FALL = 4500, T_BOUNCE = 4950, T_SWAP = 4750, T_END = 6300;
    const HALF = Math.PI/2;
