      const S = 1 + 2.1*amp/Math.min(W,H);
      if (!swapped) viewer.style.transform = amp > .05 ? `translate(${dx.toFixed(2)}px,${dy.toFixed(2)}px) scale(${S.toFixed(5)})` : '';
      // --- polvo y escombros
      const px = W, py = H + yOff, ca = Math.cos(phi), sa = Math.sin(phi);
      const faceAt = (s,off) => [px + (-(bw+off))*ca + (-s*L)*sa, py - (-(bw+off))*sa + (-s*L)*ca];
      let rate = 0;
      if (t < T_RISE) rate = 70*(1 - .4*t/T_RISE); else if (t < T_HOLD) rate = 26; else if (t < T_FALL) rate = 30 + 230*u;
      accD += rate*dt;
