        flx.translate(px,py); flx.rotate(-phi);
        const sg = flx.createLinearGradient(0,0,240,0); sg.addColorStop(0,'rgba(0,0,0,.5)'); sg.addColorStop(1,'rgba(0,0,0,0)');
        flx.fillStyle = sg; flx.fillRect(0,-L,240,L);
        flx.restore();
