      flx.save(); flx.translate(px,py); flx.rotate(-phi);
      const sh = flx.createLinearGradient(-bw,0,-bw-190,0); sh.addColorStop(0,'rgba(0,0,0,.5)'); sh.addColorStop(1,'rgba(0,0,0,0)');
      flx.fillStyle = sh; flx.fillRect(-bw-190,-L,190,L);
      flx.drawImage(bld, -bw, -L, bw, L);
