        d.vy += 900*dt; d.x += d.vx*dt; d.y += d.vy*dt; d.r += d.vr*dt;
        flx.save(); flx.translate(d.x,d.y); flx.rotate(d.r); flx.fillStyle = d.g ? '#5fa83a' : (d.s > 8 ? '#8a8474' : '#5d584f');
