      const F_KF = [[0,0],[1200,0],[3200,.5],[4600,.62],[5800,1],[6600,1],[8600,0]];    // vaho del cristal
      const T_KF = [[0,0],[3000,.55],[5800,.6],[6600,.5],[8800,0]];                     // oscuridad de tormenta
      const S_KF = [[0,0],[5900,0],[6600,1]];                                           // mezcla diapositiva 8 → 9 bajo el vaho
      const G_KF = [[0,0],[7200,0],[8200,.2],[9100,0]];                                 // destello de sol al despejar
      const T_F0 = 3300, T_HIT = 4500, T_SWAP = 5950, T_END = 9100;
